import{_ as e,c as o,o as t,a2 as r}from"./chunks/framework.CIiVzG-O.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1780466351000}'),i={name:"guide/faq.md"};function s(l,a,n,d,h,c){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h3 id="什么是-gomoku" tabindex="-1">什么是 Gomoku？ <a class="header-anchor" href="#什么是-gomoku" aria-label="Permalink to &quot;什么是 Gomoku？&quot;">​</a></h3><p>Gomoku 是一款面向 macOS 的五子棋/棋谱查看与联机对弈应用，支持人机对战、联机对战与本地保存对局（<code>.sgf</code>）。</p><h3 id="支持哪些-macos-版本" tabindex="-1">支持哪些 macOS 版本？ <a class="header-anchor" href="#支持哪些-macos-版本" aria-label="Permalink to &quot;支持哪些 macOS 版本？&quot;">​</a></h3><p>建议使用 macOS Monterey (12) 及以上。某些旧系统可能无法获得最佳体验。</p><h3 id="如何下载安装" tabindex="-1">如何下载安装？ <a class="header-anchor" href="#如何下载安装" aria-label="Permalink to &quot;如何下载安装？&quot;">​</a></h3><p>从项目的 Releases 页面下载签名的发行包，或直接通过项目提供的安装说明进行安装。开发者构建可参考仓库中的 README。</p><h3 id="如何进行联机对局-lan-play" tabindex="-1">如何进行联机对局（LAN Play）？ <a class="header-anchor" href="#如何进行联机对局-lan-play" aria-label="Permalink to &quot;如何进行联机对局（LAN Play）？&quot;">​</a></h3><p>打开应用的“联机 / 局域网”页面，创建房间或加入可见房间。确保授予 Local Network 权限并且所有设备在同一 Wi‑Fi 网络中。</p><h3 id="如何保存或导出对局" tabindex="-1">如何保存或导出对局？ <a class="header-anchor" href="#如何保存或导出对局" aria-label="Permalink to &quot;如何保存或导出对局？&quot;">​</a></h3><p>使用应用内的保存/导出功能将对局保存为 <code>.sgf</code> 文件，默认保存位置可在导出时选择。</p><h3 id="如何将-gomoku-设为默认打开-sgf-文件的应用" tabindex="-1">如何将 Gomoku 设为默认打开 <code>.sgf</code> 文件的应用？ <a class="header-anchor" href="#如何将-gomoku-设为默认打开-sgf-文件的应用" aria-label="Permalink to &quot;如何将 Gomoku 设为默认打开 `.sgf` 文件的应用？&quot;">​</a></h3><p>请参见文档“将 Gomoku 设为默认 SGF 查看器”的说明，在 Finder 的 Get Info 面板中修改默认打开应用。</p><h3 id="是否会上传我的数据" tabindex="-1">是否会上传我的数据？ <a class="header-anchor" href="#是否会上传我的数据" aria-label="Permalink to &quot;是否会上传我的数据？&quot;">​</a></h3><p>Gomoku 采用本地优先设计，默认不向外发送个人数据。联机对弈仅在本地网络内传输对局数据。详见隐私政策页。</p><h3 id="如何更新应用" tabindex="-1">如何更新应用？ <a class="header-anchor" href="#如何更新应用" aria-label="Permalink to &quot;如何更新应用？&quot;">​</a></h3><p>从 Releases 页面下载新版本或使用应用内更新机制（如有）。</p><h3 id="如何报告问题或请求新功能" tabindex="-1">如何报告问题或请求新功能？ <a class="header-anchor" href="#如何报告问题或请求新功能" aria-label="Permalink to &quot;如何报告问题或请求新功能？&quot;">​</a></h3><p>在项目仓库打开 issue，并附上你的 macOS 版本、Gomoku 版本、复现步骤以及日志（如有）。</p><h3 id="日志和保存数据存放在哪里" tabindex="-1">日志和保存数据存放在哪里？ <a class="header-anchor" href="#日志和保存数据存放在哪里" aria-label="Permalink to &quot;日志和保存数据存放在哪里？&quot;">​</a></h3><p>对于沙盒/商店版本，应用数据和日志通常位于：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.gomoku/Data/Library/Application Support/com.w3cub.gomoku/</span></span></code></pre></div><p>开发构建的日志可能打印到控制台或放置在项目的 <code>src-tauri</code> 目录下。</p><h3 id="可以和-ai-对弈吗" tabindex="-1">可以和 AI 对弈吗？ <a class="header-anchor" href="#可以和-ai-对弈吗" aria-label="Permalink to &quot;可以和 AI 对弈吗？&quot;">​</a></h3><p>可以。Gomoku 包含 AI 对手并提供多档难度，可在对局设置中选择。</p><p>如果这些问题没有覆盖到你的疑问，请在项目仓库创建 issue 或查看完整文档页面。</p>',26)])])}const m=e(i,[["render",s]]);export{p as __pageData,m as default};
